cat > zz_heldout_test.go <<'EOF'
package shop

import "testing"

func TestHeldoutCount(t *testing.T) {
	if got := Count(nil); got != 0 {
		t.Errorf("Count(nil) = %d, want 0", got)
	}
	if got := Count([]Line{{"a", 2}, {"b", 3}}); got != 5 {
		t.Errorf("Count = %d, want 5", got)
	}
}
EOF
go test -count=1 -run Heldout ./...; rc=$?; rm -f zz_heldout_test.go; exit $rc

cat > zz_heldout_test.go <<'EOF'
package shop

import "testing"

func TestHeldoutDiscountedClamps(t *testing.T) {
	c := Catalog{"a": {SKU: "a", Price: 1000}}
	for _, tc := range []struct{ percent, want int }{{10, 900}, {150, 0}, {-20, 1000}} {
		if got, err := Discounted(c, []Line{{"a", 1}}, tc.percent); err != nil || got != tc.want {
			t.Errorf("Discounted(%d%%) = %d, %v; want %d", tc.percent, got, err, tc.want)
		}
	}
}
EOF
go test -count=1 -run Heldout ./...; rc=$?; rm -f zz_heldout_test.go; exit $rc

